/**
 * Formats audit results as the Markdown table kept in `docs/STATUS.md`.
 * Languages are sorted by coverage so the ones that most need help come last.
 *
 * @param audit - The value returned by `auditLocales`.
 * @param languageNames - Map of language code to English name, for readable rows.
 * @returns Markdown text ending in a newline.
 */
export const renderMarkdownReport = (audit, languageNames) => {
  const rows = [...audit.results].sort((a, b) => b.coverage - a.coverage || a.code.localeCompare(b.code));
  const lines = [
    '# Translation status',
    '',
    'Generated by `npm run status`. Do not edit by hand.',
    '',
    `Every language is compared with \`locales/en.json\` (${audit.baselineKeyCount} keys). **Translated** counts keys that exist, are not empty, and are not still the English text.`,
    '',
    '| Language | Code | Translated | Missing | Still English | File says | Problems |',
    '| --- | --- | ---: | ---: | ---: | --- | --- |',
  ];
  for (const result of rows) {
    const problems = [...result.errors, ...result.warnings.filter((text) => text.startsWith('_meta'))];
    lines.push(
      `| ${languageNames[result.code] ?? result.code} | \`${result.code}\` | ${result.coverage}% | ${result.missing.length} | ${result.untranslated.length} | ${result.status} | ${problems.join('; ') || '-'} |`,
    );
  }
  lines.push('');
  return lines.join('\n');
};
